package com.yihe.framework.ehr;
import org.aspectj.lang.JoinPoint;import org.aspectj.lang.annotation.*;import org.springframework.stereotype.Component;import javax.servlet.http.HttpServletRequest;import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import static com.yihe.framework.ehr.EhrAccess.*;
/** Metadata only: never retain controller request bodies, credentials or model outputs. */
@Aspect @Component
public class ConfigurationAuditAspect {
 private final EhrAccess access;private final EhrRepository db;private final ObjectMapper json=new ObjectMapper();
 public ConfigurationAuditAspect(EhrAccess a,EhrRepository d){access=a;db=d;}
 private String[] module(String type){switch(type){case "AuditLogApi":return new String[]{"操作审计日志","data"};case "AiModelManagementApi":return new String[]{"AI模型与API配置","config"};case "AiToolManagementApi":return new String[]{"AI工具管理","config"};case "IndicatorDictionaryApi":return new String[]{"指标字典","config"};case "OcrTemplateApi":return new String[]{"OCR模板管理","config"};case "AssessmentRuleApi":return new String[]{"评估规则配置","config"};case "InterventionTemplateApi":return new String[]{"干预方案模板","config"};case "MessageTemplateApi":return new String[]{"消息模板","config"};default:return null;}}
 @Pointcut("execution(public * com.yihe.framework.ehr.*Api.save(..)) || execution(public * com.yihe.framework.ehr.*Api.test(..)) || execution(public * com.yihe.framework.ehr.AuditLogApi.export(..))") public void writes(){}
 @AfterReturning(pointcut="writes()",returning="result") public void complete(JoinPoint p,Object result){record(p,result,false);}
 @AfterThrowing(pointcut="writes()",throwing="failure") public void failure(JoinPoint p,Throwable failure){record(p,null,true);}
 @SuppressWarnings("unchecked") void record(JoinPoint point,Object result,boolean failure){String[] module=module(point.getTarget().getClass().getSimpleName());if(module==null)return;HttpServletRequest req=null;for(Object arg:point.getArgs())if(arg instanceof HttpServletRequest)req=(HttpServletRequest)arg;if(req==null)return;try{EhrActor a=access.web(req);if(a.mobile)return;boolean test=point.getSignature().getName().equals("test"),export=point.getSignature().getName().equals("export");String outcome=failure?"failed":"success";if(test&&result instanceof Map){Object data=((Map<?,?>)result).get("data");if(data instanceof Map){Object row=((Map<?,?>)data).get("record");if(row instanceof Map&&!Boolean.TRUE.equals(((Map<?,?>)row).get("success")))outcome="failed";}}
 String client=req.getHeader("User-Agent");if(client==null)client="";client=client.replaceAll("[\\r\\n\\t]"," ");if(client.length()>500)client=client.substring(0,500);String id=UUID.randomUUID().toString();Map<String,Object> metadata=map("_audit",map("module",module[0],"category",test?"ai":module[1],"type",test?"invoke":export?"export":"update","result",outcome,"ip",req.getRemoteAddr(),"client",client,"actorType",a.doctor?"医生管理端":"后台账号"),"request",map("method",req.getMethod(),"path",req.getRequestURI()));db.insert("a_health_archive_audit_logs",map("audit_id",id,"scope_code",a.scope,"data_mode",a.mode,"actor_ref",bytes(a.user),"action",test?"configuration_test":export?"audit_export":"configuration_saved","request_key",id,"reason",(test?"测试：":export?"导出：":"保存配置：")+module[0]+(outcome.equals("failed")?"（未通过）":""),"redacted_diff",json.writeValueAsString(metadata),"occurred_at",now()));
 }catch(Exception e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Configuration audit metadata could not be recorded");}}
}
